"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["44775"],{31932(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_do_recurso_da_fase.efeito_suspensivo_nao_declarado","status":422,"titulo":"O per\xedodo de recurso precisa declarar um efeito suspensivo aceito"},"descricao":{"codigo":"uniplus.selecao.configuracao_do_recurso_da_fase.efeito_suspensivo_nao_declarado","requisitos":["UNI-REQ-0440"],"oQueAconteceu":["A configura\xe7\xe3o do recurso de uma fase n\xe3o declara o **efeito suspensivo** do recurso na 1\xaa inst\xe2ncia, ou declara um que n\xe3o \xe9 uma das op\xe7\xf5es aceitas. A declara\xe7\xe3o \xe9 obrigat\xf3ria e n\xe3o tem valor padr\xe3o (UNI-REQ-0440). A recusa sai com **422**, nada \xe9 gravado, e o campo recusado \xe9 `fases[i].regraRecurso.efeitoSuspensivo`, em que `i` \xe9 a posi\xe7\xe3o da fase.","A mensagem da resposta tem duas formas, e nenhuma repete o valor enviado:","- campo ausente: \\"Declare o efeito suspensivo do recurso na 1\xaa inst\xe2ncia. Op\xe7\xf5es aceitas: efeito suspensivo para todos os recursos, sem efeito suspensivo ou a unidade respons\xe1vel pela fase de origem do ato recorrido decide em cada recurso.\\";\\n- valor recusado: \\"O efeito suspensivo declarado n\xe3o \xe9 uma das op\xe7\xf5es aceitas: efeito suspensivo para todos os recursos, sem efeito suspensivo ou a unidade respons\xe1vel pela fase de origem do ato recorrido decide em cada recurso.\\""],"comoResolver":["Informe, em `efeitoSuspensivo`, um destes tr\xeas c\xf3digos:","- `PARA_TODOS_OS_RECURSOS`: todo recurso da 1\xaa inst\xe2ncia tem efeito suspensivo; enquanto o prazo para recorrer est\xe1 aberto e, havendo recurso, at\xe9 que todos tenham decis\xe3o e o resultado definitivo esteja publicado, ficam suspensos os atos que n\xe3o podem ser desfeitos e o in\xedcio das fases posteriores;\\n- `SEM_EFEITO_SUSPENSIVO`: o recurso da 1\xaa inst\xe2ncia n\xe3o suspende nenhum ato do processo enquanto \xe9 analisado;\\n- `UNIDADE_DECIDE_EM_CADA_RECURSO`: em cada recurso da 1\xaa inst\xe2ncia, a unidade respons\xe1vel pela fase de origem do ato recorrido decide se concede o efeito suspensivo e registra a fundamenta\xe7\xe3o; s\xf3 o recurso com a concess\xe3o suspende os atos que n\xe3o podem ser desfeitos e o in\xedcio das fases posteriores.","A lista das op\xe7\xf5es, com r\xf3tulo e descri\xe7\xe3o, est\xe1 em `GET /api/selecao/efeitos-suspensivos`. A escolha vale s\xf3 para a 1\xaa inst\xe2ncia: a 2\xaa inst\xe2ncia sempre tem efeito suspensivo."],"ondeAparece":["Defini\xe7\xe3o do cronograma de fases do processo seletivo","Leitura do documento de configura\xe7\xe3o do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao do recurso da fase"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);